/bin/zsh -lc "node --input-type=module <<'NODE'
import assert from 'node:assert/strict';
import { readFileSync, writeFileSync } from 'node:fs';
import { lineFromRequest } from './src/api.js';

let errorMessage;
try {
  lineFromRequest({ sku: 'A', quantity: ' ' });
  throw new Error('invalid input unexpectedly accepted');
} catch (error) {
  errorMessage = error.message;
}
assert.equal(errorMessage, 'invalid quantity');
const result = {
  changed_file: 'src/quantity.js',
  zero_result: lineFromRequest({ sku: ' A ', quantity: '0' }),
  error_message: errorMessage,
};
writeFileSync('answer.json', JSON.stringify(result, null, 2) + '\\n');
const saved = JSON.parse(readFileSync('answer.json', 'utf8'));
assert.deepEqual(Object.keys(saved), ['changed_file', 'zero_result', 'error_message']);
assert.deepEqual(saved, result);
console.log(JSON.stringify(saved));
NODE"

